export interface ConnectorConfig {
  /** Airtable API key (Bearer token) */
  airtableApiKey: string
  /** Airtable Base ID (e.g., appXXXXXXXXXXXXXXXXXXXX) */
  baseId: string
  /** Airtable Table Name or ID */
  tableName: string
  /** Optional injected fetch for testing */
  fetch?: typeof fetch
}

export interface JotformSubmission {
  email: string
  name?: string
  phone?: string
  address?: string
  [key: string]: unknown
}

export interface HandleResult {
  recordId: string
  updatedFields: string[]
}

async function fetchWithAuth(
  url: string,
  options: RequestInit,
  apiKey: string,
  customFetch?: typeof fetch
): Promise<Response> {
  const headers = new Headers(options.headers)
  headers.set('Authorization', `Bearer ${apiKey}`)
  headers.set('Content-Type', 'application/json')
  const fetchFn = customFetch ?? fetch
  return fetchFn(url, { ...options, headers })
}

function buildFilterFormula(email: string): string {
  const escaped = email.replace(/'/g, "\\'")
  return `{email}='${escaped}'`
}

function encodeFilterFormula(formula: string): string {
  return encodeURIComponent(formula)
}

function pickNonEmptyFields(payload: JotformSubmission): Record<string, string> {
  const fields: Record<string, string> = {}
  if (payload.name && payload.name.trim() !== '') fields.Name = payload.name.trim()
  if (payload.phone && payload.phone.trim() !== '') fields.Phone = payload.phone.trim()
  if (payload.address && payload.address.trim() !== '') fields.Address = payload.address.trim()
  return fields
}

export async function handle(
  payload: JotformSubmission,
  config: ConnectorConfig
): Promise<HandleResult> {
  if (!payload.email || payload.email.trim() === '') {
    throw new Error('Missing required field: email')
  }

  const { airtableApiKey, baseId, tableName, fetch } = config
  const email = payload.email.trim()

  // Step 1: Find record by email
  const formula = buildFilterFormula(email)
  const encodedFormula = encodeFilterFormula(formula)
  const getUrl = `https://api.airtable.com/v0/${baseId}/${tableName}?filterByFormula=${encodedFormula}`

  const getResponse = await fetchWithAuth(getUrl, { method: 'GET' }, airtableApiKey, fetch)

  if (!getResponse.ok) {
    throw new Error(`Airtable GET failed: ${getResponse.status} ${getResponse.statusText} at ${getUrl}`)
  }

  const getData = (await getResponse.json()) as { records: Array<{ id: string; fields: Record<string, unknown> }> }

  if (!getData.records || getData.records.length === 0) {
    throw new Error(`No Airtable record found for email: ${email}`)
  }

  if (getData.records.length > 1) {
    throw new Error(`Multiple Airtable records found for email: ${email} (found ${getData.records.length})`)
  }

  const recordId = getData.records[0].id

  // Step 2: Build PATCH body with only non-empty fields
  const fieldsToUpdate = pickNonEmptyFields(payload)

  if (Object.keys(fieldsToUpdate).length === 0) {
    return { recordId, updatedFields: [] }
  }

  const patchUrl = `https://api.airtable.com/v0/${baseId}/${tableName}/${recordId}`
  const patchBody = JSON.stringify({ fields: fieldsToUpdate })

  const patchResponse = await fetchWithAuth(patchUrl, { method: 'PATCH', body: patchBody }, airtableApiKey, fetch)

  if (!patchResponse.ok) {
    throw new Error(`Airtable PATCH failed: ${patchResponse.status} ${patchResponse.statusText} at ${patchUrl}`)
  }

  return { recordId, updatedFields: Object.keys(fieldsToUpdate) }
}

import { describe, it, expect, vi } from 'vitest'
import { handle, ConnectorConfig, JotformSubmission } from './connector'
import { SOURCE_EXAMPLE, contractFetch, fakeFetch, jsonResponse, TARGET_ENDPOINTS } from './fixtures'

describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch()
    const config: ConnectorConfig = {
      airtableApiKey: 'test-api-key',
      baseId: 'appTestBase',
      tableName: 'Table1',
      fetch
    }
    const result = await handle(SOURCE_EXAMPLE as unknown as JotformSubmission, config)
    expect(calls.length).toBeGreaterThan(0)
    expect(result.recordId).toBe('rec123')
    expect(result.updatedFields).toEqual(['Name', 'Phone', 'Address'])
  })
})

describe('handle', () => {
  it('throws when email is missing', async () => {
    const { fetch, calls } = fakeFetch(() => jsonResponse({ error: 'not found' }, 404))
    const config: ConnectorConfig = {
      airtableApiKey: 'test-key',
      baseId: 'appTest',
      tableName: 'Table1',
      fetch
    }
    const payload = { name: 'John', phone: '555', address: '123 St' } as JotformSubmission
    await expect(handle(payload, config)).rejects.toThrow('Missing required field: email')
    expect(calls.length).toBe(0)
  })

  it('throws when email is empty string', async () => {
    const { fetch, calls } = fakeFetch(() => jsonResponse({ error: 'not found' }, 404))
    const config: ConnectorConfig = {
      airtableApiKey: 'test-key',
      baseId: 'appTest',
      tableName: 'Table1',
      fetch
    }
    const payload = { email: '   ', name: 'John' } as JotformSubmission
    await expect(handle(payload, config)).rejects.toThrow('Missing required field: email')
    expect(calls.length).toBe(0)
  })

  it('sends Bearer auth header on both requests', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url.includes('filterByFormula')) {
        return jsonResponse({ records: [{ id: 'rec456', fields: {} }] })
      }
      return jsonResponse({ id: 'rec456', fields: { Name: 'Jane' } })
    })
    const config: ConnectorConfig = {
      airtableApiKey: 'secret-key-123',
      baseId: 'appTest',
      tableName: 'Table1',
      fetch
    }
    const payload: JotformSubmission = { email: 'jane@example.com', name: 'Jane Doe' }
    await handle(payload, config)
    expect(calls.length).toBe(2)
    expect(calls[0].headers.get('authorization')).toBe('Bearer secret-key-123')
    expect(calls[1].headers.get('authorization')).toBe('Bearer secret-key-123')
  })

  it('includes only non-empty fields in PATCH body', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url.includes('filterByFormula')) {
        return jsonResponse({ records: [{ id: 'rec789', fields: {} }] })
      }
      return jsonResponse({ id: 'rec789', fields: { Name: 'Bob', Phone: '555-0000' } })
    })
    const config: ConnectorConfig = {
      airtableApiKey: 'test-key',
      baseId: 'appTest',
      tableName: 'Table1',
      fetch
    }
    const payload: JotformSubmission = {
      email: 'bob@example.com',
      name: 'Bob Smith',
      phone: '',
      address: '   '
    }
    const result = await handle(payload, config)
    expect(result.updatedFields).toEqual(['Name'])
    expect(calls[1].json).toEqual({ fields: { Name: 'Bob Smith' } })
  })

  it('returns empty updatedFields when all optional fields are empty', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url.includes('filterByFormula')) {
        return jsonResponse({ records: [{ id: 'rec999', fields: {} }] })
      }
      return jsonResponse({ id: 'rec999', fields: {} })
    })
    const config: ConnectorConfig = {
      airtableApiKey: 'test-key',
      baseId: 'appTest',
      tableName: 'Table1',
      fetch
    }
    const payload: JotformSubmission = { email: 'empty@example.com', name: '', phone: null, address: undefined }
    const result = await handle(payload, config)
    expect(result.updatedFields).toEqual([])
    expect(calls.length).toBe(1) // Only GET, no PATCH
  })

  it('throws on non-2xx GET response with status and endpoint', async () => {
    const { fetch, calls } = fakeFetch(() => jsonResponse({ error: 'Unauthorized' }, 401))
    const config: ConnectorConfig = {
      airtableApiKey: 'bad-key',
      baseId: 'appTest',
      tableName: 'Table1',
      fetch
    }
    const payload: JotformSubmission = { email: 'test@example.com' }
    await expect(handle(payload, config)).rejects.toThrow('Airtable GET failed: 401 Unauthorized at https://api.airtable.com/v0/appTest/Table1?filterByFormula=%7Bemail%7D%3D%27test%40example.com%27')
    expect(calls.length).toBe(1)
  })

  it('throws on non-2xx PATCH response with status and endpoint', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url.includes('filterByFormula')) {
        return jsonResponse({ records: [{ id: 'rec111', fields: {} }] })
      }
      return jsonResponse({ error: 'Rate limited' }, 429)
    })
    const config: ConnectorConfig = {
      airtableApiKey: 'test-key',
      baseId: 'appTest',
      tableName: 'Table1',
      fetch
    }
    const payload: JotformSubmission = { email: 'patch@example.com', name: 'Patch User' }
    await expect(handle(payload, config)).rejects.toThrow('Airtable PATCH failed: 429 Too Many Requests at https://api.airtable.com/v0/appTest/Table1/rec111')
    expect(calls.length).toBe(2)
  })

  it('throws when no record found for email', async () => {
    const { fetch, calls } = fakeFetch(() => jsonResponse({ records: [] }))
    const config: ConnectorConfig = {
      airtableApiKey: 'test-key',
      baseId: 'appTest',
      tableName: 'Table1',
      fetch
    }
    const payload: JotformSubmission = { email: 'missing@example.com' }
    await expect(handle(payload, config)).rejects.toThrow('No Airtable record found for email: missing@example.com')
    expect(calls.length).toBe(1)
  })

  it('throws when multiple records found for email', async () => {
    const { fetch, calls } = fakeFetch(() => jsonResponse({
      records: [
        { id: 'rec1', fields: {} },
        { id: 'rec2', fields: {} }
      ]
    }))
    const config: ConnectorConfig = {
      airtableApiKey: 'test-key',
      baseId: 'appTest',
      tableName: 'Table1',
      fetch
    }
    const payload: JotformSubmission = { email: 'duplicate@example.com' }
    await expect(handle(payload, config)).rejects.toThrow('Multiple Airtable records found for email: duplicate@example.com (found 2)')
    expect(calls.length).toBe(1)
  })

  it('properly encodes email with special characters in filterByFormula', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url.includes('filterByFormula')) {
        expect(req.url).toContain('%7Bemail%7D%3D%27o%27neil%40example.com%27')
        return jsonResponse({ records: [{ id: 'recO', fields: {} }] })
      }
      return jsonResponse({ id: 'recO', fields: { Name: 'ONeill' } })
    })
    const config: ConnectorConfig = {
      airtableApiKey: 'test-key',
      baseId: 'appTest',
      tableName: 'Table1',
      fetch
    }
    const payload: JotformSubmission = { email: "o'neil@example.com", name: "O'Neil" }
    await handle(payload, config)
    expect(calls.length).toBe(2)
  })
})

